export function siteStay(site,mode='park'){const p=SITE_STAYS[site.id];return p?{...p,days:mode==='highlights'?p.fast:p.slow}:null;}
export const resolveSiteDays=(site,settings,days={})=>days[site.id]??siteStay(site,settings.stayMode)?.days??site.days;
